def complementSet (M : CoxeterMatrix I) (J : Set I) :
    Set (relativeSubspace J × relativeSubspace J) :=
  {p | ∀ r ∈ retainedRoots M J, ¬(p.1.val r = 0 ∧ p.2.val r = 0)}

