/-- Keep exactly those roots whose evaluation is not identically zero on `Θ_J`. -/
def retainedRoots (M : CoxeterMatrix I) (J : Set I) : Set (Vector I) :=
  {r | r ∈ roots M ∧ ∃ φ : relativeSubspace J, φ.val r ≠ 0}

